import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_versions(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-2] if '/' in proj['path'] else proj['path']
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(name, {})[pkg['id']] = pkg['resolvedVersion']
    return result

bv = get_versions(b)
av = get_versions(a)
print('BASELINE:')
for p, pkgs in sorted(bv.items()):
    for pkg, ver in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {ver}')
print()
print('AFTER CPM:')
for p, pkgs in sorted(av.items()):
    for pkg, ver in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {ver}')
"

